  all.push(...recs);
  if (start + 100 > n) break;
  await new Promise((r) => setTimeout(r, 1200));
}
await writeFile('/tmp/alma/records.xml', all.map((r, i) => `<!--REC ${i}-->\n${r}`).join('\n'));
console.log('collected', all.length);
