/**
 * The Zentralbibliothek Zürich's catalogue (swisscovery, Alma SRU) as a second
 * discovery channel for the *same* e-rara items.
 *
 * e-rara's own SRU endpoint only indexes `dc.title`, `dc.subject` and
 * `dc.creator`, so a Zürich map the catalogue files under another heading can stay
 * invisible to it (the historic 1588/1595 city views, the 1715 “Delineation der
 * Statt Zürich”, the 1741 “Delineatio Pagi Tigurini”, the 1795 canton map …). The
 * ZB/UB catalogue's Alma SRU — documented by the ZB's own Datenmap
 * (`data.zb.uzh.ch/map/…/page/alma-sru`) and by Ex Libris — answers the richer
 * `alma.genre_form` index (“Altkarte” = historical map) and states the e-rara DOI
 * of the digitised copy in MARC 856 $u.
 *
 * A MARC hit is only a *lead*: the DOI landing page's `og:url` names the IIIF item
 * (corpus + title id) verbatim, and the record is built from that item's IIIF
 * manifest like every other record. No metadata is taken from the MARC record
 * alone, and a lead whose manifest states no `Kartendaten` extent or no holding
 * library is dropped exactly like an e-rara SRU hit. A lead whose catalogue title
 * already exists in the seed is skipped before its manifest is requested — the
 * channel supplements the seed, it does not duplicate it.
 *
 * Probed 2026-10-19: `alma.genre_form=Altkarte and alma.all=e-rara and
 * alma.all=Zürich` answers 211 records; the candidates are read in pages of 50
 * (the server's cap, whatever `maximumRecords` asks).
 */
const ALMA_SRU = {
  id: 'zb-katalog-altkarten',
  name: 'Zürcher Altkarten aus dem ZB-Katalog (swisscovery)',
  endpoint: 'https://uzb.swisscovery.ch/view/sru/41SLSP_UZB',
  query: 'alma.genre_form=Altkarte and alma.all=e-rara and alma.all=Zürich',
  pageSize: 50,
  maxRecords: 250,
  candidateCap: 190,
  recordCap: 36,
  perDecade: 3,
  rule:
    'leads from the ZB catalogue\'s Alma SRU (alma.genre_form=Altkarte, the e-rara DOI in ' +
    'MARC 856 $u): a lead is resolved through its DOI landing page to the e-rara IIIF ' +
    'item (og:url states corpus and title id), then built from that manifest with the same ' +
    'gates as every other set — map genre, stated publication year, stated holding library, ' +
    'stated “Kartendaten” extent; the centre of the extent must lie inside the canton window, ' +
    'leads whose catalogue title already exists in the seed are skipped, and the selection is ' +
    'one entry per title and year, oldest first with at most three records per publication ' +
    'decade (cap 36)',
};

function almaUrl(cql, start = 1) {
  return (
    `${ALMA_SRU.endpoint}?version=1.2&operation=searchRetrieve&recordSchema=marcxml` +
    `&maximumRecords=${ALMA_SRU.pageSize}&startRecord=${start}&query=${encodeURIComponent(cql)}`
  );
}

/** MARC subfields of one datafield; a repeated tag returns every value. */
function marcSubfields(chunk, tag, code) {
  const fields = chunk.match(new RegExp(`<datafield[^>]*tag="${tag}"[^>]*>[\\s\\S]*?</datafield>`, 'g')) || [];
  const out = [];
  for (const field of fields) {
    const m = field.match(new RegExp(`<subfield code="${code}">([\\s\\S]*?)</subfield>`));
    if (m) out.push(decode(m[1]));
  }
  return out;
}

/** One Alma SRU/MARC hit → a *lead* (DOI + catalogue title/year), never a record. */
function parseAlmaRecord(chunk) {
  const mmsId = (chunk.match(/<controlfield tag="001">([^<]+)<\/controlfield>/) || [])[1] || null;
  const doi = (chunk.match(/10\.3931\/e-rara-\d+/) || [])[0] || null;
  const title = [marcSubfields(chunk, '245', 'a')[0], marcSubfields(chunk, '245', 'b')[0]]
    .filter(Boolean)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
  return {
    mmsId,
    doi: doi ? `https://doi.org/${doi}` : null,
    title,
    year: parseYear(marcSubfields(chunk, '264', 'c')[0] || marcSubfields(chunk, '260', 'c')[0] || ''),
    creators: [...marcSubfields(chunk, '100', 'a'), ...marcSubfields(chunk, '700', 'a')].filter(Boolean),
    genres: marcSubfields(chunk, '655', 'a'),
    places: [...marcSubfields(chunk, '651', 'a'), ...marcSubfields(chunk, '650', 'a')],
  };
}

async function almaSearch(cql, maxRecords) {
  const hits = [];
  let total = Infinity;
  for (let start = 1; start <= maxRecords && start <= total; start += ALMA_SRU.pageSize) {
    const xml = await get(almaUrl(cql, start));
    total = Number((xml.match(/<numberOfRecords>(\d+)</) || [])[1]) || 0;
    const chunks = [
      ...xml.matchAll(/<record xmlns="http:\/\/www\.loc\.gov\/MARC21\/slim">([\s\S]*?)<\/record>/g),
    ].map((m) => m[1]);
    if (!chunks.length) break;
    for (const chunk of chunks) {
      const hit = parseAlmaRecord(chunk);
      if (hit) hits.push(hit);
    }
    if (chunks.length < ALMA_SRU.pageSize) break;
    await sleep(150);
  }
  return hits;
}

/**
 * Resolve an e-rara DOI to the IIIF item the provider actually serves. The DOI
 * number is *not* the IIIF title id (e.g. `e-rara-26717` → item `8602391`), so the
 * landing page's `og:url` — which states the corpus and the id — is the only thing
 * the manifest URL is built from. Returns null when the page does not state it.
 */
async function resolveERaraItem(doi) {
  const html = await get(doi, { as: 'text', timeout: 20000 });
  const m = html.match(/og:url"\s+content="https?:\/\/www\.e-rara\.ch\/([a-z0-9_]+)\/(\d+)"/);
  if (!m) return null;
  return { corpus: m[1], titleId: m[2] };
}

async function main() {

